package com.yuegang.zhihui.notification.security;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.common.security.*;import jakarta.servlet.http.*;import java.time.*;import java.util.*;
public final class NotificationSecurity{private final InternalUserContextSignature users;private final InternalServiceSignature services;public NotificationSecurity(byte[]k){users=new InternalUserContextSignature(k,Clock.systemUTC(),Duration.ofSeconds(30));services=new InternalServiceSignature(k,Clock.systemUTC(),Duration.ofSeconds(30));}public long user(HttpServletRequest r){return context(r).user;}public long require(HttpServletRequest r,String permission){var c=context(r);if(!c.roles.contains("ADMIN")&&!c.permissions.contains(permission))throw new BusinessException(ErrorCode.PERMISSION_DENIED);return c.user;}public void service(HttpServletRequest r){try{String n=h(r,"X-YGH-Service");Instant t=Instant.ofEpochMilli(Long.parseLong(h(r,"X-YGH-Service-Timestamp")));if(!services.verify(new InternalServiceSignature.Metadata(n,r.getMethod(),r.getRequestURI(),t),h(r,"X-YGH-Service-Signature")))throw f();}catch(Exception e){throw f();}}private Context context(HttpServletRequest r){try{String u=h(r,"X-YGH-User-Id");var roles=v(r.getHeader("X-YGH-Roles"));var perms=v(r.getHeader("X-YGH-Permissions"));var m=new InternalUserContextSignature.Metadata(u,roles,perms,h(r,"X-Trace-Id"),h(r,"X-Request-Id"),r.getMethod(),r.getRequestURI(),Instant.ofEpochMilli(Long.parseLong(h(r,"X-YGH-User-Context-Timestamp"))));if(!users.verify(m,h(r,"X-YGH-User-Context-Signature")))throw f();return new Context(Long.parseLong(u),roles,perms);}catch(BusinessException e){throw e;}catch(Exception e){throw f();}}private record Context(long user,List<String>roles,List<String>permissions){}private static String h(HttpServletRequest r,String n){String v=r.getHeader(n);if(v==null||v.isBlank())throw f();return v;}private static List<String>v(String x){return x==null||x.isBlank()?List.of():List.of(x.split(","));}private static BusinessException f(){return new BusinessException(ErrorCode.UNAUTHENTICATED);}}
